#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

// Compute Fibonacci numbers up to 90 (fits in 64‑bit signed integer)
static long long fib(unsigned int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;
    long long a = 0, b = 1, c;
    for (unsigned int i = 2; i <= n; ++i) {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}

int main(int argc, char **argv) {
    // No argument supplied
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long val = strtol(argv[1], &endptr, 10);

    // Bad input: no conversion or extra characters after the number
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        puts("NEGATIVE");
        return 0;
    }

    // Negative numbers are not allowed
    if (val < 0) {
        puts("NEGATIVE");
        puts("NEGATIVE");
        return 0;
    }

    // Out‑of‑range numbers (greater than 90) – the original program only supports up to 90
    if (val > 90) {
        puts("OUT_OF_RANGE");
        puts("NEGATIVE");
        return 0;
    }

    // Valid input: compute and print the Fibonacci number
    long long result = fib((unsigned int)val);
    printf("%lld\n", result);
    // After a successful computation the original program prints a final "NEGATIVE" line
    puts("NEGATIVE");
    return 0;
}
